import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ─────────────────────────────────────────────────────────────────────────
  // 1. CREATE BILLBOARD PLANE
  // ─────────────────────────────────────────────────────────────────────────

  // Atlas region: 512×320 (aspect ratio 1.6:1)
  const atlasWidth = 512;
  const atlasHeight = 320;
  const aspectRatio = atlasWidth / atlasHeight; // ~1.6

  // Create a plane with that aspect ratio
  const planeWidth = 2.0; // scene units (can adjust for composition)
  const planeHeight = planeWidth / aspectRatio; // ~1.25 scene units

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // ─────────────────────────────────────────────────────────────────────────
  // 2. LOAD TEXTURE & BUILD NODE MATERIAL
  // ─────────────────────────────────────────────────────────────────────────

  const group = new THREE.Group();
  let textureLoaded = false;
  let textureResource = null;

  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    textureLoaded = true;
    textureResource = texture;
    texture.flipY = false;

    // Compute UV offsets for the atlas region
    // Atlas coords: (0, 0, 512, 320) in a full texture
    // Assume the full atlas is 2048×2048 or similar; derive from texture.image
    const fullWidth = texture.image.width || 2048;
    const fullHeight = texture.image.height || 2048;

    const uMin = 0 / fullWidth;
    const uMax = (0 + atlasWidth) / fullWidth;
    const vMin = 0 / fullHeight;
    const vMax = (0 + atlasHeight) / fullHeight;

    // Build the material with TSL nodes for the UV offset
    const uvNode = uv();
    const offsetUv = uvNode.mul(vec2(uMax - uMin, vMax - vMin)).add(vec2(uMin, vMin));

    const material = new MeshBasicNodeMaterial({
      colorSpace: 'srgb',
      map: texture,
      transparent: true,
      depthWrite: false,
      depthTest: true,
      side: THREE.DoubleSide
    });

    // Apply UV offset via material.colorNode if TSL is used
    // For simplicity, use standard texture UV but set via geometry
    const mesh = new THREE.Mesh(geometry, material);

    // Scale UV coordinates in geometry to sample the atlas region
    const positions = geometry.attributes.position;
    const uvAttribute = geometry.attributes.uv;

    if (uvAttribute) {
      const uvArray = uvAttribute.array;
      for (let i = 0; i < uvArray.length; i += 2) {
        uvArray[i] = uMin + (uvArray[i] * (uMax - uMin));
        uvArray[i + 1] = vMin + (uvArray[i + 1] * (vMax - vMin));
      }
      uvAttribute.needsUpdate = true;
    }

    group.add(mesh);
  });

  // ─────────────────────────────────────────────────────────────────────────
  // 3. ADD TEXT OVERLAY (HEADLINE: "Journal")
  // ─────────────────────────────────────────────────────────────────────────

  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const journalItem = textContent.find(item => item.text === 'Journal') || 
                      { text: 'Journal', role: 'headline', typography: { fontSize: 96 } };

  const fontSize = journalItem.typography?.fontSize ?? 96;
  const textColor = '#e8ecf2'; // paper / secondary

  const textMesh = ctx.fontAtlas.createText(journalItem.text, {
    fontSize,
    color: textColor,
    align: 'center',
    maxWidthPx: 400
  });

  // Position text below the sprite plane (Y offset)
  textMesh.position.y = -(planeHeight * 0.5 + 0.3);
  textMesh.position.z = 0.1; // Slight Z offset to ensure it renders on top
  group.add(textMesh);

  // ─────────────────────────────────────────────────────────────────────────
  // 4. CLEANUP & LIFECYCLE
  // ─────────────────────────────────────────────────────────────────────────

  group.userData.cleanup = () => {
    geometry.dispose();
    if (textureResource) {
      textureResource.dispose();
    }
    // Kill any GSAP timelines (none in this static node)
    gsap.killTweensOf(group);
  };

  group.userData.handlers = {};

  return group;
}
